#!/usr/bin/env bash
# A Dart model with build_runner output, and a hook config that protects it.
set -euo pipefail
mkdir -p .claude lib
cat > .claude/agent-workflow.json <<'EOF'
{
  "protected": [
    {
      "glob": "**/*.g.dart",
      "reason": "Generated by build_runner. Edit the source .dart file, then run `dart run build_runner build`."
    }
  ]
}
EOF
cat > lib/user.dart <<'EOF'
import 'package:json_annotation/json_annotation.dart';

part 'user.g.dart';

@JsonSerializable()
class User {
  User({required this.name});

  final String name;

  factory User.fromJson(Map<String, dynamic> json) => _$UserFromJson(json);
  Map<String, dynamic> toJson() => _$UserToJson(this);
}
EOF
cat > lib/user.g.dart <<'EOF'
// GENERATED CODE - DO NOT MODIFY BY HAND

part of 'user.dart';

User _$UserFromJson(Map<String, dynamic> json) => User(name: json['name'] as String);

Map<String, dynamic> _$UserToJson(User instance) => <String, dynamic>{'name': instance.name};
EOF
